//! The root system's GUMBO functions, for the system assertions.

use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

pub fn inRange100(v: i32) -> bool
{
  (-100i32 <= v) &
    (v <= 100i32)
}

pub fn inConsumeRange(s: SysPropStructSplit_Data_Model::StructXY) -> bool
{
  (-200i32 <= s.x) &
    (s.x <= 200i32) &
    (-200i32 <= s.y) &
    (s.y <= 200i32)
}

pub fn inRange200(v: i32) -> bool
{
  (-200i32 <= v) &
    (v <= 200i32)
}

pub fn mergedReflectsGen(
  m: SysPropStructSplit_Data_Model::StructXY,
  g: SysPropStructSplit_Data_Model::StructXY) -> bool
{
  (implies!(
    (g.x < 100i32),
    (m.x == g.x + 1i32))) &
    (implies!(
      (g.x == 100i32),
      (m.x == 100i32))) &
    (m.y == g.y - 1i32)
}
